.st-ladder { display: grid; grid-template-columns: repeat(6, 1fr); gap: 0; align-items: stretch; border: 1px solid var(--border); border-radius: 10px; overflow: hidden; background: var(--surface); }
.st-rung { padding: 16px 14px; display: flex; flex-direction: column; gap: 6px; border-inline-end: 1px solid var(--border); position: relative; }
.st-rung:last-child { border-inline-end: 0; }
.st-rung .num { font-family: var(--font-mono); font-size: 10px; letter-spacing: .08em; color: var(--fg-subtle); text-transform: uppercase; }
.st-rung .ttl { font-size: 12.5px; font-weight: 600; color: var(--fg); margin-top: 2px; }
.st-rung .desc { font-size: 12px; color: var(--fg-muted); line-height: 1.5; }
.st-rung .pill { align-self: flex-start; }
@media (max-width: 920px) { .st-ladder { grid-template-columns: repeat(2, 1fr); } .st-rung { border-inline-end: 0; border-bottom: 1px solid var(--border); } }
.st-matrix { width: 100%; border-collapse: collapse; }
.st-matrix th, .st-matrix td { text-align: start; padding: 12px 14px; border-bottom: 1px solid var(--border); font-size: 13px; vertical-align: middle; }
.st-matrix th { font-weight: 500; color: var(--fg-subtle); font-size: 11px; letter-spacing: .04em; text-transform: uppercase; }
.st-matrix td.icol { display: flex; align-items: center; gap: 8px; }
.st-matrix tr:last-child td { border-bottom: 0; }
.st-sweep { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.st-cell { display: flex; flex-direction: column; gap: 8px; padding: 14px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }
.st-cell .lbl { font-family: var(--font-mono); font-size: 10px; color: var(--fg-subtle); letter-spacing: .06em; text-transform: uppercase; }
@media (max-width: 760px) { .st-sweep { grid-template-columns: 1fr; } }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/** Merge class names, de-duplicating conflicting Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
